mapper.select:
SELECT * FROM (
  SELECT yrt_id AS yrtId, emp_id AS empId, base_year AS baseYear, run_label AS runLabel,
         confirm_yn AS confirmYn, created_at AS createdAt, updated_at AS updatedAt
  FROM ytsim_header
  WHERE emp_id = #{empId}
    AND base_year = #{baseYear}
    AND (#{confirmedOnly} = 0 OR confirm_yn='Y')
  ORDER BY confirm_yn DESC, updated_at DESC
) WHERE ROWNUM = 1

mapper.delete:
DELETE FROM ytsim_item WHERE yrt_id IN (
  SELECT yrt_id FROM ytsim_header
  WHERE emp_id = #{empId} AND base_year = #{baseYear} AND confirm_yn='N'
);
DELETE FROM yrt_result_total WHERE yrt_id IN (
  SELECT yrt_id FROM ytsim_header
  WHERE emp_id = #{empId} AND base_year = #{baseYear} AND confirm_yn='N'
);
DELETE FROM ytsim_header
WHERE emp_id = #{empId} AND base_year = #{baseYear} AND confirm_yn='N';

DELETE FROM ytsim_item WHERE yrt_id = #{yrtId};
DELETE FROM yrt_result_total WHERE yrt_id = #{yrtId};
DELETE FROM ytsim_header WHERE yrt_id = #{yrtId} AND confirm_yn='N';

mapper.select:
SELECT NVL(SUM(i.expected_amount),0)
FROM ytsim_header h
JOIN ytsim_item   i ON i.yrt_id = h.yrt_id
WHERE h.emp_id = #{empId}
  AND h.base_year = #{baseYear}
  AND (
        (#{yrtId} IS NOT NULL AND h.yrt_id = #{yrtId})
     OR (#{yrtId} IS NULL     AND h.confirm_yn = 'N')
      )
  AND i.item_class = '세액공제'
